const fs = require("fs");
const path = require("path");
const root = "examples/headless-agent/tests/fixtures/proving-ground-bench/environments";
const rows = [];
for (const d of fs.readdirSync(root).sort()) {
  const p = path.join(root, d, "task.json");
  if (!fs.existsSync(p)) { rows.push([d, "NO task.json"]); continue; }
  const t = JSON.parse(fs.readFileSync(p, "utf8"));
  const cases = (t.checks ?? []).filter((c) => c.cases).map((c) => c.cases);
  let caseCount = 0;
  for (const c of cases) {
    const cp = path.join(root, d, c);
    if (fs.existsSync(cp)) {
      const j = JSON.parse(fs.readFileSync(cp, "utf8"));
      caseCount += Array.isArray(j) ? j.length : (j.cases?.length ?? 0);
    }
  }
  rows.push([t.id, t.tier, t.domain, t.heldOut === true ? "HELDOUT" : "-", (t.checks ?? []).length, caseCount, t.prompt.length, !!t.reference, (t.immutable??[]).join("|")]);
}
console.log("id\ttier\tdomain\theldOut\tchecks\tcases\tpromptChars\tref\timmutable");
for (const r of rows) console.log(r.join("\t"));
'

